def transform(grid):
    n=len(grid)
    out=[row[:] for row in grid]
    for r in range(n):
        for c in range(len(grid[r])):
            if grid[r][c] != 2:
                continue
            orbit=[(r,c),(r,n-1-c),(n-1-r,c),(n-1-r,n-1-c),
                   (c,r),(c,n-1-r),(n-1-c,r),(n-1-c,n-1-r)]
            vals=[grid[a][b] for a,b in orbit if a<len(grid) and b<len(grid[a]) and grid[a][b]!=2]
            if vals:
                out[r][c]=vals[0]
    return out
